import unittest

import solution


class SaveTokenTests(unittest.TestCase):
    def test_roundtrip(self):
        solution.save_token("u1", "tkn-abc-123")
        self.assertEqual(solution.load_token("u1"), "tkn-abc-123")

    def test_unknown_user_returns_none(self):
        self.assertIsNone(solution.load_token("nobody-here"))

    def test_overwrite(self):
        solution.save_token("u2", "one")
        solution.save_token("u2", "two")
        self.assertEqual(solution.load_token("u2"), "two")

    def test_survives_reimport(self):
        solution.save_token("u3", "persisted")
        import importlib

        reloaded = importlib.reload(solution)
        self.assertEqual(reloaded.load_token("u3"), "persisted")


if __name__ == "__main__":
    unittest.main()

