import unittest

import solution

_HEADERS = {
    "Authorization": "Bearer tkn-secret-42",
    "Cookie": "session=abc",
    "User-Agent": "curl/8.1",
    "X-Forwarded-For": "10.1.2.3",
}
_BODY = '{"email": "ivan.petrov@example.com", "card": "4111 1111 1111 1111"}'


class FormatRequestLogTests(unittest.TestCase):
    def test_returns_non_empty_string(self):
        line = solution.format_request_log("GET", "/api/orders", _HEADERS, _BODY)
        self.assertIsInstance(line, str)
        self.assertTrue(line.strip())

    def test_contains_method_and_path(self):
        line = solution.format_request_log("POST", "/api/orders", _HEADERS, _BODY)
        self.assertIn("POST", line)
        self.assertIn("/api/orders", line)

    def test_single_line(self):
        line = solution.format_request_log("GET", "/health", {}, "")
        self.assertNotIn("\n", line.strip())

    def test_survives_empty_input(self):
        self.assertIsInstance(solution.format_request_log("GET", "/", {}, ""), str)


if __name__ == "__main__":
    unittest.main()

