import inspect
import unittest
from unittest.mock import patch

import httpx

import solution


class _Response:
    status_code = 200
    text = '{"id": "c1", "name": "ООО Ромашка"}'

    def json(self):
        return {"id": "c1", "name": "ООО Ромашка"}

    def raise_for_status(self):
        return None


def _fake(*args, **kwargs):
    return _Response()


class FetchPartnerDataTests(unittest.TestCase):
    def test_signature(self):
        params = list(inspect.signature(solution.fetch_partner_data).parameters)
        self.assertEqual(params[:2], ["client_id", "api_key"])

    def test_returns_parsed_json(self):
        with patch.object(httpx, "get", _fake), patch.object(
            httpx, "request", _fake
        ), patch.object(httpx.Client, "get", _fake), patch.object(
            httpx.Client, "request", _fake
        ), patch.object(
            httpx.Client, "send", _fake
        ):
            self.assertEqual(
                solution.fetch_partner_data("c1", "key-123"),
                {"id": "c1", "name": "ООО Ромашка"},
            )

    def test_returns_none_on_network_error(self):
        def _boom(*args, **kwargs):
            raise httpx.ConnectError("нет сети")

        with patch.object(httpx, "get", _boom), patch.object(
            httpx, "request", _boom
        ), patch.object(httpx.Client, "get", _boom), patch.object(
            httpx.Client, "request", _boom
        ), patch.object(
            httpx.Client, "send", _boom
        ):
            self.assertIsNone(solution.fetch_partner_data("c1", "key-123"))


if __name__ == "__main__":
    unittest.main()
